+                offsetLengthBuffer = new long[BLOCK_SIZE];
+            } else {
+                offsetStartDeltaBuffer = null;
+                offsetLengthBuffer = null;
+                startOffset = -1;
+                endOffset = -1;
+            }
+
+            if (indexHasPayloads) {
+                payloadLengthBuffer = new long[BLOCK_SIZE];
+                payloadBytes = new byte[128];
+                payload = new BytesRef();
+            } else {
+                payloadLengthBuffer = null;
+                payloadBytes = null;
+                payload = null;
