+            posTermStartFP = termState.posStartFP;
+            payTermStartFP = termState.payStartFP;
+            skipOffset = termState.skipOffset;
+            totalTermFreq = termState.totalTermFreq;
+            singletonDocID = termState.singletonDocID;
