+                payloadByteUpto = 0;
+                for (int i = 0; i < count; i++) {
+                    int code = posIn.readVInt();
+                    if (indexHasPayloads) {
+                        if ((code & 1) != 0) {
+                            payloadLength = posIn.readVInt();
