+            int toSkip = posPendingCount - freq;
+            // if (DEBUG) {
+            // System.out.println(" FPR.skipPositions: toSkip=" + toSkip);
+            // }
+
+            final int leftInBlock = BLOCK_SIZE - posBufferUpto;
+            if (toSkip < leftInBlock) {
+                int end = posBufferUpto + toSkip;
+                while (posBufferUpto < end) {
+                    if (indexHasPayloads) {
+                        payloadByteUpto += (int) payloadLengthBuffer[posBufferUpto];
+                    }
+                    posBufferUpto++;
+                }
+            } else {
+                toSkip -= leftInBlock;
+                while (toSkip >= BLOCK_SIZE) {
+                    assert posIn.getFilePointer() != lastPosBlockFP;
+                    pforUtil.skip(posIn);
+
+                    if (indexHasPayloads) {
+                        // Skip payloadLength block:
+                        pforUtil.skip(payIn);
+
+                        // Skip payloadBytes block:
+                        int numBytes = payIn.readVInt();
+                        payIn.seek(payIn.getFilePointer() + numBytes);
+                    }
+
+                    if (indexHasOffsets) {
+                        pforUtil.skip(payIn);
+                        pforUtil.skip(payIn);
+                    }
+                    toSkip -= BLOCK_SIZE;
+                }
+                refillPositions();
+                payloadByteUpto = 0;
+                posBufferUpto = 0;
+                while (posBufferUpto < toSkip) {
+                    if (indexHasPayloads) {
+                        payloadByteUpto += (int) payloadLengthBuffer[posBufferUpto];
+                    }
+                    posBufferUpto++;
+                }
+            }
+
+            position = 0;
+            lastStartOffset = 0;
+        }
+
+        @Override
+        public int nextPosition() throws IOException {
+            assert posPendingCount > 0;
+
+            if (posPendingFP != -1) {
+                posIn.seek(posPendingFP);
+                posPendingFP = -1;
+
+                if (payPendingFP != -1 && payIn != null) {
+                    payIn.seek(payPendingFP);
+                    payPendingFP = -1;
+                }
+
+                // Force buffer refill:
+                posBufferUpto = BLOCK_SIZE;
+            }
+
+            if (posPendingCount > freq) {
+                skipPositions();
+                posPendingCount = freq;
+            }
+
+            if (posBufferUpto == BLOCK_SIZE) {
+                refillPositions();
+                posBufferUpto = 0;
+            }
+            position += (int) posDeltaBuffer[posBufferUpto];
+
+            if (indexHasPayloads) {
+                payloadLength = (int) payloadLengthBuffer[posBufferUpto];
+                payload.bytes = payloadBytes;
+                payload.offset = payloadByteUpto;
+                payload.length = payloadLength;
+                payloadByteUpto += payloadLength;
+            }
+
+            if (indexHasOffsets) {
+                startOffset = lastStartOffset + (int) offsetStartDeltaBuffer[posBufferUpto];
+                endOffset = startOffset + (int) offsetLengthBuffer[posBufferUpto];
+                lastStartOffset = startOffset;
+            }
+
+            posBufferUpto++;
+            posPendingCount--;
+            return position;
+        }
+
+        @Override
+        public int startOffset() {
+            return startOffset;
+        }
+
+        @Override
+        public int endOffset() {
+            return endOffset;
+        }
+
+        @Override
+        public BytesRef getPayload() {
+            if (payloadLength == 0) {
+                return null;
+            } else {
+                return payload;
+            }
+        }
+
+        @Override
+        public long cost() {
+            return docFreq;
+        }
+    }
